const upsertReconciliationFinding = `-- name: UpsertReconciliationFinding :one

INSERT INTO openrails.reconciliation_findings (
    merchant_id, finding_type, subject_key, severity, status,
    recommended_action, evidence, resolved_at, resolution,
    first_seen_run, last_seen_run
) VALUES (
    $1, $2, $3,
    $4, $5, $6,
    $7::jsonb,
    CASE WHEN $5::text = 'auto_fixed' THEN now() ELSE NULL END,
    CASE WHEN $5::text = 'auto_fixed' THEN 'enforced' ELSE NULL END,
    $8, $8
)
ON CONFLICT (merchant_id, finding_type, subject_key) DO UPDATE SET
    severity = EXCLUDED.severity,
    status = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN 'ignored'
        ELSE EXCLUDED.status
    END,
    recommended_action = EXCLUDED.recommended_action,
    evidence = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN openrails.reconciliation_findings.evidence
        ELSE EXCLUDED.evidence
    END,
    resolved_at = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN openrails.reconciliation_findings.resolved_at
        WHEN EXCLUDED.status = 'auto_fixed' THEN EXCLUDED.resolved_at
        ELSE NULL
    END,
    resolution = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN openrails.reconciliation_findings.resolution
        WHEN EXCLUDED.status = 'auto_fixed' THEN EXCLUDED.resolution
        ELSE NULL
    END,
    -- #787: an inline auto_fixed transition (the only resolution this upsert
    -- itself can produce; fixed/ignored come via the separate admin/auto-
    -- resolve statements below) is a resolution — clear the notify linkage so
    -- a future reopen of this identity notifies again.
    notified_at = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN openrails.reconciliation_findings.notified_at
        WHEN EXCLUDED.status = 'auto_fixed' THEN NULL
        ELSE openrails.reconciliation_findings.notified_at
    END,
    notified_severity = CASE
        WHEN openrails.reconciliation_findings.status = 'ignored' THEN openrails.reconciliation_findings.notified_severity
        WHEN EXCLUDED.status = 'auto_fixed' THEN NULL
        ELSE openrails.reconciliation_findings.notified_severity
    END,
    last_seen_run = COALESCE(EXCLUDED.last_seen_run, openrails.reconciliation_findings.last_seen_run),
    last_seen_at = now(),
    updated_at = now()
RETURNING id, merchant_id, finding_type, subject_key, severity, status, recommended_action, first_seen_run, last_seen_run, last_seen_at, resolved_at, resolution, operator_notes, created_at, updated_at, evidence, resolved_by, notified_at, notified_severity
`

type UpsertReconciliationFindingParams struct {
	MerchantID        uuid.UUID
	FindingType       string
	SubjectKey        string
	Severity          string
	Status            string
	RecommendedAction *string
	Evidence          []byte
	RunID             *uuid.UUID
}

// ============================================================================
// Findings: stable-identity upsert + lifecycle
// ============================================================================
// Re-runs UPDATE the standing finding for (merchant, finding_type, subject_key).
// A previously fixed/auto_fixed finding that reappears is
// REOPENED with the freshly computed status; an ignored finding stays ignored
// (an operator explicitly silenced this identity).
func (q *Queries) UpsertReconciliationFinding(ctx context.Context, arg UpsertReconciliationFindingParams) (OpenrailsReconciliationFinding, error) {
	row := q.db.QueryRow(ctx, upsertReconciliationFinding,
		arg.MerchantID,
		arg.FindingType,
		arg.SubjectKey,
		arg.Severity,
		arg.Status,
		arg.RecommendedAction,
		arg.Evidence,
		arg.RunID,
	)
	var i OpenrailsReconciliationFinding
	err := row.Scan(
		&i.ID,
		&i.MerchantID,
		&i.FindingType,
		&i.SubjectKey,
		&i.Severity,
		&i.Status,
		&i.RecommendedAction,
		&i.FirstSeenRun,
		&i.LastSeenRun,
		&i.LastSeenAt,
		&i.ResolvedAt,
		&i.Resolution,
		&i.OperatorNotes,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Evidence,
		&i.ResolvedBy,
		&i.NotifiedAt,
		&i.NotifiedSeverity,
	)
	return i, err
}

const upsertReconciliationState = `-- name: UpsertReconciliationState :one

INSERT INTO openrails.reconciliation_state (
    merchant_id, source_domain, fully_reconciled, last_full_pull_at, updated_at
) VALUES (
    $1::uuid, $2::text,
    $3::boolean, $4::timestamptz, now()
)
ON CONFLICT (merchant_id, source_domain) DO UPDATE SET
    fully_reconciled = EXCLUDED.fully_reconciled,
    last_full_pull_at = COALESCE(EXCLUDED.last_full_pull_at, openrails.reconciliation_state.last_full_pull_at),
    updated_at = now()
RETURNING id, merchant_id, source_domain, fully_reconciled, last_full_pull_at, updated_at
`

type UpsertReconciliationStateParams struct {
	MerchantID      uuid.UUID
	SourceDomain    string
	FullyReconciled bool
	LastFullPullAt  *time.Time
}

// #511 Convergence Engine: per-(merchant, source_domain) confirmed-absence gate.
// WRITERS (#665): reconcile.MarkReconciledSourceDomains flips a domain
// automatically after a pull PROVES it — exhaustive coverage
// (SnapshotCoverage, not mere event-window watermark freshness) of EVERY
// configured provider account whose rail could hold that domain's sources.
// `grants` is admin/local-sourced, so no pull ever proves it — it stays a
// manual/bulk-import decision. The flag is a ratchet: never auto-unset.
// Mark a source domain's reconciliation watermark. Pass fully_reconciled=true +
// last_full_pull_at after a completed authoritative pull/import for that domain.
func (q *Queries) UpsertReconciliationState(ctx context.Context, arg UpsertReconciliationStateParams) (OpenrailsReconciliationState, error) {
	row := q.db.QueryRow(ctx, upsertReconciliationState,
		arg.MerchantID,
		arg.SourceDomain,
		arg.FullyReconciled,
		arg.LastFullPullAt,
	)
	var i OpenrailsReconciliationState
	err := row.Scan(
		&i.ID,
		&i.MerchantID,
		&i.SourceDomain,
		&i.FullyReconciled,
		&i.LastFullPullAt,
		&i.UpdatedAt,
	)
	return i, err
}
